async function seed() {
  // Get or create seed user
  let userId;
  const { data: existingUsers } = await sb.auth.admin.listUsers({ page: 1, perPage: 100 });
  const seedUser = existingUsers?.users?.find(u => u.email === 'seed-buyers@lotscout.com');
  if (seedUser) {
    userId = seedUser.id;
    console.log('Using existing seed user:', userId);
  } else {
    const { data: { user: newUser }, error: createErr } = await sb.auth.admin.createUser({
      email: 'seed-buyers@lotscout.com',
      password: 'SeedBuyers2026!',
      email_confirm: true,
    });
    if (createErr) { console.error('Failed to create user:', createErr); return; }
    userId = newUser.id;
    console.log('Created seed user:', userId);
  }

  const EXTRA = EXTRA_BUYERS.map(b => ({
    ...b,
    user_id: userId,
    display_name: b.display_company,
    target_regions: b.target_state ? [b.target_state] : ['National'],
    timeline: TIMELINE,
    status: 'active',
  }));

  console.log(`Total extra buyers to potentially insert: ${EXTRA.length}`);

  // Check existing
  const { data: existing, error: fetchErr } = await sb
    .from('buyer_requests')
    .select('display_company, target_state')
    .not('display_company', 'is', null);

  if (fetchErr) { console.error('Fetch error:', fetchErr); return; }

  const existingSet = new Set(existing.map(r => `${r.display_company}||${r.target_state}`));
  const newBuyers = EXTRA.filter(b => !existingSet.has(`${b.display_company}||${b.target_state}`));

  console.log(`Already in DB: ${existing.length}`);
  console.log(`New buyers to insert: ${newBuyers.length}`);

  if (newBuyers.length === 0) { console.log('Nothing to insert — all already seeded!'); return; }

  const BATCH = 50;
  let inserted = 0;
  for (let i = 0; i < newBuyers.length; i += BATCH) {
    const batch = newBuyers.slice(i, i + BATCH);
    const { error } = await sb.from('buyer_requests').insert(batch);
    if (error) {
      console.error(`Batch ${i}-${i+BATCH} error:`, error.message);
    } else {
      inserted += batch.length;
      process.stdout.write(`\rInserted ${inserted}/${newBuyers.length}`);
    }
  }
  console.log(`\nDone! Inserted ${inserted} new buyers.`);
}

seed().catch(console.error);
